// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title SimpleForwarder
 * @dev A simple ERC2771 forwarder for testing purposes
 */
contract SimpleForwarder is ERC2771Context, Ownable {
    mapping(address => uint256) private _nonces;
    mapping(address => bool) private _relayers;

    event RelayerAdded(address indexed relayer);
    event RelayerRemoved(address indexed relayer);

    constructor() ERC2771Context(address(this)) Ownable(msg.sender) {
        _relayers[msg.sender] = true;
    }

    // Override required functions to resolve conflicts
    function _msgSender() internal view override(ERC2771Context, Context) returns (address) {
        return ERC2771Context._msgSender();
    }

    function _msgData() internal view override(ERC2771Context, Context) returns (bytes calldata) {
        return ERC2771Context._msgData();
    }

    function _contextSuffixLength() internal view override(ERC2771Context, Context) returns (uint256) {
        return ERC2771Context._contextSuffixLength();
    }

    function getNonce(address user) external view returns (uint256) {
        return _nonces[user];
    }

    function isRelayer(address relayer) external view returns (bool) {
        return _relayers[relayer];
    }

    function addRelayer(address relayer) external onlyOwner {
        _relayers[relayer] = true;
        emit RelayerAdded(relayer);
    }

    function removeRelayer(address relayer) external onlyOwner {
        _relayers[relayer] = false;
        emit RelayerRemoved(relayer);
    }

    function execute(
        address userAddress,
        bytes calldata functionSignature,
        bytes32 sigR,
        bytes32 sigS,
        uint8 sigV
    ) external payable returns (bytes memory) {
        require(_relayers[msg.sender], "SimpleForwarder: caller is not a relayer");

        // Increment nonce
        _nonces[userAddress]++;

        // For testing purposes, we'll just return empty bytes
        // In a real implementation, you would verify the signature and execute the call
        return "";
    }
}

